def cache_sim(capacity, ttl, ops):
    from collections import defaultdict

    cache = {}  # key -> (value, write_time)
    lru_order = []  # list of keys in order of use (most recent at end)
    results = []

    def is_expired(key, current_time):
        if key not in cache:
            return True
        value, write_time = cache[key]
        return current_time >= write_time + ttl

    def mark_most_recent(key):
        if key in lru_order:
            lru_order.remove(key)
        lru_order.append(key)

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Check if key already exists and is not expired
            if key in cache and not is_expired(key, t):
                # Key exists and is valid, update it
                cache[key] = (value, t)
                mark_most_recent(key)
            else:
                # Key is new or expired
                if key in cache:
                    # Remove expired entry
                    lru_order.remove(key)

                # Check if we need to evict
                if len(cache) >= capacity:
                    # Evict the least recently used
                    lru_key = lru_order.pop(0)
                    del cache[lru_key]

                # Add new entry
                cache[key] = (value, t)
                mark_most_recent(key)

        elif op[0] == 'get':
            _, t, key = op

            if key in cache and not is_expired(key, t):
                value, write_time = cache[key]
                mark_most_recent(key)
                results.append(value)
            else:
                results.append(-1)

    return results

